def predict_output(rule_check=True):
    """
    Rule: 
    - Background 5 -> 5
    - Special 6 -> 6 if col % 5 != 1, else 3
    - Exception: if horizontal neighbor is 6 and col % 5 == 1, keep as 6
    """
    result = np.zeros_like(input_array)

    for r in range(23):
        for c in range(25):
            if input_array[r, c] == 5:
                result[r, c] = 5
            elif input_array[r, c] == 6:
                if c % 5 != 1:
                    result[r, c] = 6
                elif rule_check:
                    # Check horizontal neighbors
                    has_left_6 = c > 0 and input_array[r, c-1] == 6
                    has_right_6 = c < 24 and input_array[r, c+1] == 6
                    if has_left_6 or has_right_6:
                        result[r, c] = 6
                    else:
                        result[r, c] = 3
                else:
                    result[r, c] = 3
    return result

